def _walk_segment(
    shape: tuple[int, int],
    r: int,
    c: int,
    dr: int,
    dc: int,
    length: int,
    blocked: set[tuple[int, int]],
    path_cells: list[tuple[int, int]],
) -> tuple[int, int] | None:
    for _ in range(length):
        nr, nc = r + dr, c + dc
        if not _in_bounds(shape, nr, nc) or (nr, nc) in blocked:
            return None
        blocked.add((nr, nc))
        path_cells.append((nr, nc))
